-- Phase 4 Part 2: resident invitations and derived resident access.
-- Generated by prisma migrate diff, followed by a hand-written section.

-- AlterTable
ALTER TABLE "invitations" ADD COLUMN     "person_id" UUID;

-- AddForeignKey
ALTER TABLE "invitations" ADD CONSTRAINT "invitations_organisation_id_person_id_fkey" FOREIGN KEY ("organisation_id", "person_id") REFERENCES "persons"("organisation_id", "id") ON DELETE RESTRICT ON UPDATE RESTRICT;


-- =============================================================================================
-- Hand-written below this line: resident invitations, own-profile visibility, and derived
-- resident grants. See docs/security/ACCESS_CONTROL.md section 6.
-- =============================================================================================

-- A resident invitation links a person profile to a login; it never creates a membership.
ALTER TABLE "invitations" ADD CONSTRAINT "invitations_resident_shape"
  CHECK (("role" = 'RESIDENT') = ("person_id" IS NOT NULL)
         AND ("person_id" IS NULL OR "scope_type" = 'ORGANISATION'));

-- A user may see their own resident profiles in any organisation, before choosing one (to list
-- "my organisations"). Every other person row stays tenant-only.
CREATE POLICY "persons_select_own" ON "persons" FOR SELECT
  USING ("user_id" = app_current_user_id());

-- Organisations are visible in user context to members (as before) and to active residents.
DROP POLICY "organisations_select" ON "organisations";
CREATE POLICY "organisations_select" ON "organisations" FOR SELECT
  USING (
    "id" = app_current_organisation_id()
    OR EXISTS (
      SELECT 1 FROM "memberships" m
      WHERE m."organisation_id" = "organisations"."id"
        AND m."user_id" = app_current_user_id()
        AND m."status" = 'ACTIVE'
    )
    OR EXISTS (
      SELECT 1 FROM "persons" p
      WHERE p."organisation_id" = "organisations"."id"
        AND p."user_id" = app_current_user_id()
        AND p."status" = 'ACTIVE'
    )
  );

-- ---------------------------------------------------------------------------------------------
-- Derived resident grants: the units on which a user is OWNER, TENANT or HOUSEHOLD_MEMBER today.
--   * only ACTIVE person profiles linked to the user;
--   * only non-voided records whose inclusive period contains the property's LOCAL date today
--     (the property's IANA time zone decides when a tenancy starts and ends);
--   * runs as the caller under RLS, so it only ever sees the current tenant's rows.
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION app_resident_grants(p_user uuid)
  RETURNS TABLE ("role" text, "property_id" uuid, "unit_id" uuid)
  LANGUAGE sql STABLE
  AS $$
  WITH me AS (
    SELECT "id", "organisation_id" FROM "persons" WHERE "user_id" = p_user AND "status" = 'ACTIVE'
  ),
  local_today AS (
    SELECT "id" AS "property_id", (now() AT TIME ZONE "time_zone")::date AS "d" FROM "properties"
  )
  SELECT 'OWNER', o."property_id", o."unit_id"
    FROM "ownerships" o
    JOIN me ON me."id" = o."person_id" AND me."organisation_id" = o."organisation_id"
    JOIN local_today t ON t."property_id" = o."property_id"
   WHERE o."voided_at" IS NULL
     AND o."effective_from" <= t."d" AND (o."effective_to" IS NULL OR o."effective_to" >= t."d")
  UNION
  SELECT 'TENANT', tn."property_id", tn."unit_id"
    FROM "tenancy_occupants" oc
    JOIN me ON me."id" = oc."person_id" AND me."organisation_id" = oc."organisation_id"
    JOIN "tenancies" tn ON tn."id" = oc."tenancy_id" AND tn."organisation_id" = oc."organisation_id"
    JOIN local_today t ON t."property_id" = tn."property_id"
   WHERE tn."voided_at" IS NULL
     AND tn."start_date" <= t."d" AND (tn."end_date" IS NULL OR tn."end_date" >= t."d")
  UNION
  SELECT 'HOUSEHOLD_MEMBER', h."property_id", h."unit_id"
    FROM "household_members" h
    JOIN me ON me."id" = h."person_id" AND me."organisation_id" = h."organisation_id"
    JOIN local_today t ON t."property_id" = h."property_id"
   WHERE h."voided_at" IS NULL
     AND h."valid_from" <= t."d" AND (h."valid_to" IS NULL OR h."valid_to" >= t."d")
$$;

GRANT EXECUTE ON FUNCTION app_resident_grants(uuid) TO veyra_app;
